ent-certificate-data: \n    client-key-data: \n','2026-01-23 09:26:33.445670'),(14,'kubeconfig','21880489319120378','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:30:46.118341'),(15,'kubeconfig','9768381371725907','https://mirrors.tuna.tsinghua.edu.cn/jenkins/updates/update-center.json\r\n\r\n\r\npipeline {\r\n    //在名为kubernetes的Agent中执行流水线，会拉起一个Slave Pod\r\n    agent {\r\n        kubernetes {\r\n            cloud \'Slave\'\r\n            yaml \'\'\'\r\n            apiVersion: v1\r\n            kind: Pod\r\n            spec:\r\n              volumes: \r\n              - name: data\r\n                nfs:\r\n                  server: 192.168.37.147\r\n                  path: /nfs/maven \r\n              - name: dockersocket\r\n                hostPath:\r\n                  path: /run/docker.sock\r\n              containers:\r\n              - name: maven\r\n                image: 8.138.232.71:82/cicd/maven:3.8.6\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: data\r\n                  mountPath: /root/.m2 \r\n              - name: nodejs\r\n                image: 8.138.232.71:82/cicd/nodejs:14.20\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: sonar\r\n                image: 8.138.232.71:82/cicd/sonar-scanner:2.3.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: docker\r\n                image: 8.138.232.71:82/cicd/docker:20.10\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: dockersocket\r\n                  mountPath: /run/docker.sock \r\n              - name: kubectl\r\n                image: 8.138.232.71:82/cicd/kubectl:1.23.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n            \'\'\'\r\n        }\r\n    }\r\n    stages {\r\n        stage(\'maven测试\') {\r\n            steps {\r\n              container(\'maven\'){\r\n                sh \'mvn --version\'\r\n              }\r\n            }\r\n        }\r\n        stage(\'nodejs测试\'){\r\n            steps{\r\n              container(\'nodejs\'){\r\n                sh \'node -v\'\r\n              }\r\n        	}\r\n        }\r\n        stage(\'docker测试\'){\r\n          steps{\r\n            container(\'docker\'){\r\n              sh \'docker ps\'\r\n            }\r\n          }\r\n        }\r\n        stage(\'kubectl测试\'){\r\n          steps{\r\n            container(\'kubectl\'){\r\n              sh \'kubectl version\'\r\n            }\r\n          }\r\n        }\r\n    }\r\n}\r\n\r\n\r\nFSxCDysyNqoYbK_y1QzD\r\n\r\n\r\ncheckout scmGit(branches: [[name: \'*/master\']], extensions: [], userRemoteConfigs: [[credentialsId: \'gitlab-root-token\', url: \'http://web.gitlab.com/root/ruoyo-cloud.git\']])\r\n\r\n\r\n172.16.32.133\r\n\r\n\r\ngateway部署探测探测8080端口\r\n\r\n\r\n\r\n\r\nwithSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n\r\n\r\n\r\n\r\n优化:对每个组件进行创建对应项目实现单个组件的部署\r\n设置当单个组件的代码改变时候只对\r\n对组件进行限值内存和cpu\r\nprometheus监控数据\r\npipe流水线优化:并行构建,代码检测,检测通知,变量标签,定义定时任务删除因多改动导致的多镜像所造成的资源\r\n监控\r\nsum(container_memory_working_set_bytes{container!=\"\",namespace=\"ruoyi-cloud\"}) by (pod)/1024/1024/1024：查看ruoyi下的pod的内存使用量\r\n\r\n\r\n\r\n\r\n\r\npipeline {\r\n    //在名为kubernetes的Agent中执行流水线\r\n    agent {\r\n        kubernetes {\r\n            cloud \'kubernetes\'\r\n            yaml \'\'\'\r\n            apiVersion: v1\r\n            kind: Pod\r\n            spec:\r\n              nodeSelector:\r\n                disk: cicd\r\n              volumes: \r\n              - name: data\r\n                nfs:\r\n                  server: 192.168.37.147\r\n                  path: /nfs/maven \r\n              - name: dockersocket\r\n                hostPath:\r\n                  path: /run/docker.sock\r\n              containers:\r\n              - name: maven\r\n                image: 8.138.232.71:82/cicd/maven:3.8.6\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: data\r\n                  mountPath: /root/.m2 \r\n              - name: nodejs\r\n                image: 8.138.232.71:82/cicd/nodejs:14.20\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: sonar\r\n                image: 8.138.232.71:82/cicd/sonar-scanner:2.3.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: docker\r\n                image: 8.138.232.71:82/cicd/docker:20.10\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: dockersocket\r\n                  mountPath: /run/docker.sock \r\n              - name: kubectl\r\n                image: 8.138.232.71:82/cicd/kubectl:1.23.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n            \'\'\'\r\n        }\r\n    }\r\n\r\n    //定义全局变量\r\n    environment{\r\n      //修改仓库地址\r\n      Gitlab_URL = \'http://web.gitlab.com/root/ruoyo-cloud.git\'\r\n  \r\n      //认证的token无需修改，这个token前边创建时是全局token\r\n      Gitlab_token = \'gitlab-root-token\'\r\n    }\r\n\r\n    stages {\r\n        stage(\'拉取项目\') {\r\n            steps {\r\n              container(\'maven\'){\r\n                checkout scmGit(branches: [[name: \'*/master\']], extensions: [], userRemoteConfigs: [[credentialsId: \"$Gitlab_token\", url: \"$Gitlab_URL\"]])\r\n\r\n                //查看项目文件\r\n                sh \'ls -l\'\r\n\r\n                //查看当前项目所在路径\r\n                sh \'pwd\'\r\n              }\r\n            }\r\n        }\r\n        stage(\'项目检测\'){\r\n          //通过parallel属性同时执行多个步骤来检测代码\r\n          parallel{\r\n            //定义步骤\r\n            stage(\'检测Gateway\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测Auth\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测System\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测Monitor\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'检测结果\'){\r\n          steps{\r\n              container(\'sonar\'){\r\n                script{\r\n                  timeout(5){\r\n                    def qg = waitForQualityGate()\r\n                    if (qg.status != \'OK\'){\r\n                      error \"检测失败，失败的原因: ${qg.status}\"\r\n                    }\r\n                  }\r\n                }\r\n              }\r\n          }\r\n        }\r\n        stage(\'项目编译\'){\r\n          //通过parallel属性同时执行多个步骤来构建项目\r\n          parallel{\r\n            //定义步骤\r\n            stage(\'编译Gateway\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译Auth\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译System\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译Monitor\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译UI\'){\r\n              environment{\r\n                AppName = \"ruoyi-ui\"\r\n              }\r\n              steps {\r\n                container(\'nodejs\'){\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      npm install --registry=https://registry.npmmirror.com && \\\r\n                      npm run build:prod\'\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        //该步骤无需修改\r\n        stage(\'生成镜像Tag\'){\r\n          steps{\r\n            container(\'maven\'){\r\n              script{\r\n                //获取本次git提交的commit的ID（git log -n1 --pretty=format:%h），并把ID存储到变量中\r\n                env.COMMITID = sh(returnStdout: true, script: \"git log -n1 --pretty=format:%h\").trim()\r\n                //获取本次镜像的构建时间（date +%Y%m%d_%H%M）,并把时间存储到变量中\r\n                env.BuildTime = sh(returnStdout: true, script: \"date +%Y%m%d_%H%M\").trim()\r\n                //完整的镜像Tag\r\n                env.ImageTag = COMMITID + \"_\" + BuildTime\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'构建镜像\'){\r\n          //通过parallel属性同时执行多个步骤来构建镜像\r\n          parallel{\r\n            stage(\'构建Gateway镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建Auth镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\