er: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:37:02.002950'),(22,'kubeconfig','7679413520934045','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:40:44.836363'),(23,'kubeconfig','9775408929865417','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:40:46.364928'),(24,'kubeconfig','5866944938967019','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:40:47.507640'),(25,'kubeconfig','9926015967707995','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:40:47.648224'),(26,'kubeconfig','9382947110845722','https://mirrors.tuna.tsinghua.edu.cn/jenkins/updates/update-center.json\r\n\r\n\r\npipeline {\r\n    //在名为kubernetes的Agent中执行流水线，会拉起一个Slave Pod\r\n    agent {\r\n        kubernetes {\r\n            cloud \'Slave\'\r\n            yaml \'\'\'\r\n            apiVersion: v1\r\n            kind: Pod\r\n            spec:\r\n              volumes: \r\n              - name: data\r\n                nfs:\r\n                  server: 192.168.37.147\r\n                  path: /nfs/maven \r\n              - name: dockersocket\r\n                hostPath:\r\n                  path: /run/docker.sock\r\n              containers:\r\n              - name: maven\r\n                image: 8.138.232.71:82/cicd/maven:3.8.6\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: data\r\n                  mountPath: /root/.m2 \r\n              - name: nodejs\r\n                image: 8.138.232.71:82/cicd/nodejs:14.20\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: sonar\r\n                image: 8.138.232.71:82/cicd/sonar-scanner:2.3.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: docker\r\n                image: 8.138.232.71:82/cicd/docker:20.10\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: dockersocket\r\n                  mountPath: /run/docker.sock \r\n              - name: kubectl\r\n                image: 8.138.232.71:82/cicd/kubectl:1.23.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n            \'\'\'\r\n        }\r\n    }\r\n    stages {\r\n        stage(\'maven测试\') {\r\n            steps {\r\n              container(\'maven\'){\r\n                sh \'mvn --version\'\r\n              }\r\n            }\r\n        }\r\n        stage(\'nodejs测试\'){\r\n            steps{\r\n              container(\'nodejs\'){\r\n                sh \'node -v\'\r\n              }\r\n        	}\r\n        }\r\n        stage(\'docker测试\'){\r\n          steps{\r\n            container(\'docker\'){\r\n              sh \'docker ps\'\r\n            }\r\n          }\r\n        }\r\n        stage(\'kubectl测试\'){\r\n          steps{\r\n            container(\'kubectl\'){\r\n              sh \'kubectl version\'\r\n            }\r\n          }\r\n        }\r\n    }\r\n}\r\n\r\n\r\nFSxCDysyNqoYbK_y1QzD\r\n\r\n\r\ncheckout scmGit(branches: [[name: \'*/master\']], extensions: [], userRemoteConfigs: [[credentialsId: \'gitlab-root-token\', url: \'http://web.gitlab.com/root/ruoyo-cloud.git\']])\r\n\r\n\r\n172.16.32.133\r\n\r\n\r\ngateway部署探测探测8080端口\r\n\r\n\r\n\r\n\r\nwithSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n\r\n\r\n\r\n\r\n优化:对每个组件进行创建对应项目实现单个组件的部署\r\n设置当单个组件的代码改变时候只对\r\n对组件进行限值内存和cpu\r\nprometheus监控数据\r\npipe流水线优化:并行构建,代码检测,检测通知,变量标签,定义定时任务删除因多改动导致的多镜像所造成的资源\r\n监控\r\nsum(container_memory_working_set_bytes{container!=\"\",namespace=\"ruoyi-cloud\"}) by (pod)/1024/1024/1024：查看ruoyi下的pod的内存使用量\r\n\r\n\r\n\r\n\r\n\r\npipeline {\r\n    //在名为kubernetes的Agent中执行流水线\r\n    agent {\r\n        kubernetes {\r\n            cloud \'kubernetes\'\r\n            yaml \'\'\'\r\n            apiVersion: v1\r\n            kind: Pod\r\n            spec:\r\n              nodeSelector:\r\n                disk: cicd\r\n              volumes: \r\n              - name: data\r\n                nfs:\r\n                  server: 192.168.37.147\r\n                  path: /nfs/maven \r\n              - name: dockersocket\r\n                hostPath:\r\n                  path: /run/docker.sock\r\n              containers:\r\n              - name: maven\r\n                image: 8.138.232.71:82/cicd/maven:3.8.6\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: data\r\n                  mountPath: /root/.m2 \r\n              - name: nodejs\r\n                image: 8.138.232.71:82/cicd/nodejs:14.20\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: sonar\r\n                image: 8.138.232.71:82/cicd/sonar-scanner:2.3.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: docker\r\n                image: 8.138.232.71:82/cicd/docker:20.10\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: dockersocket\r\n                  mountPath: /run/docker.sock \r\n              - name: kubectl\r\n                image: 8.138.232.71:82/cicd/kubectl:1.23.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n            \'\'\'\r\n        }\r\n    }\r\n\r\n    //定义全局变量\r\n    environment{\r\n      //修改仓库地址\r\n      Gitlab_URL = \'http://web.gitlab.com/root/ruoyo-cloud.git\'\r\n  \r\n      //认证的token无需修改，这个token前边创建时是全局token\r\n      Gitlab_token = \'gitlab-root-token\'\r\n    }\r\n\r\n    stages {\r\n        stage(\'拉取项目\') {\r\n            steps {\r\n              container(\'maven\'){\r\n                checkout scmGit(branches: [[name: \'*/master\']], extensions: [], userRemoteConfigs: [[credentialsId: \"$Gitlab_token\", url: \"$Gitlab_URL\"]])\r\n\r\n                //查看项目文件\r\n                sh \'ls -l\'\r\n\r\n                //查看当前项目所在路径\r\n                sh \'pwd\'\r\n              }\r\n            }\r\n        }\r\n        stage(\'项目检测\'){\r\n          //通过parallel属性同时执行多个步骤来检测代码\r\n          parallel{\r\n            //定义步骤\r\n            stage(\'检测Gateway\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测Auth\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测System\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测Monitor\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'检测结果\'){\r\n          steps{\r\n              container(\'sonar\'){\r\n                script{\r\n                  timeout(5){\r\n                    def qg = waitForQualityGate()\r\n                    if (qg.status != \'OK\'){\r\n                      error \"检测失败，失败的原因: ${qg.status}\"\r\n                    }\r\n                  }\r\n                }\r\n              }\r\n          }\r\n        }\r\n        stage(\'项目编译\'){\r\n          //通过parallel属性同时执行多个步骤来构建项目\r\n          parallel{\r\n            //定义步骤\r\n            stage(\'编译Gateway\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译Auth\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译System\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译Monitor\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译UI\'){\r\n              environment{\r\n                AppName = \"ruoyi-ui\"\r\n              }\r\n              steps {\r\n                container(\'nodejs\'){\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      npm install --registry=https://registry.npmmirror.com && \\\r\n                      npm run build:prod\'\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        //该步骤无需修改\r\n        stage(\'生成镜像Tag\'){\r\n          steps{\r\n            container(\'maven\'){\r\n              script{\r\n                //获取本次git提交的commit的ID（git log -n1 --pretty=format:%h），并把ID存储到变量中\r\n                env.COMMITID = sh(returnStdout: true, script: \"git log -n1 --pretty=format:%h\").trim()\r\n                //获取本次镜像的构建时间（date +%Y%m%d_%H%M）,并把时间存储到变量中\r\n                env.BuildTime = sh(returnStdout: true, script: \"date +%Y%m%d_%H%M\").trim()\r\n                //完整的镜像Tag\r\n                env.ImageTag = COMMITID + \"_\" + BuildTime\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'构建镜像\'){\r\n          //通过parallel属性同时执行多个步骤来构建镜像\r\n          parallel{\r\n            stage(\'构建Gateway镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建Auth镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建System镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建Monitor镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建UI镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-ui\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'项目部署\'){\r\n          //通过parallel属性同时执行多个步骤来构建镜像\r\n          parallel{\r\n            stage(\'部署Gateway\'){\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-gateway:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署Auth\'){\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-auth:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署System\'){\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-system:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署Monitor\'){\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-monitor:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署UI\'){\r\n              environment{\r\n                AppName=\"ruoyi-ui\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-ui:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n    }\r\n}\r\n\r\n\r\nkubectl exec -it argocd-repo-server-6b4b89dd7c-gcp54 -n argocd -- /bin/sh\r\njMVY7KxZ6dA6W3_2HFmp\r\n10.96.106.218\r\n修改打开的最大文件数\r\n\r\n\r\n#！/bin/bash\r\nshell是基于于内核进行交互的语言无需进行编译就可直接输出\r\ngrep    查找文件内容   -c :输出匹配的行 	-n:输出匹配的值,并标出行号	-v:输出不匹配的值\r\n“”和‘’的区别 \"\"会输出变量的值而‘’当正常字符使用\r\n正则表达式 \\     \\<the\\>   [a-c]     \\{\\}  grep \r\nunset readonly\r\n${}\r\n\'\' “”``  \\\r\nread  $?  \r\n${}\r\n${!var}\r\n${var/1/2}\r\n${var/#1/2}\r\n${var/%1/2}\r\n${! *}\r\n${#var}\r\n${var:m} ${var:m:len} \r\neval(值的二次引用)\r\ncat 1.txt <<EOF\r\nSD S \r\nS AD \r\nS DA\r\nEOF\r\n[ -z var ]\r\n[ -n var ]\r\n[ a -a b ]\r\n[ b -o c ]\r\n[ ! c ]\r\n-f -L -d -e -s -r -w -x \r\nNF NR\r\n;: && || \r\ndmesg\r\ntail -n -f \r\ncontainerd\r\ndocker inspect \r\ngrep -A 5 -B 5\r\ngrep -C 5(行前后)\r\ndocker -v(--mount)\r\n容器的目录挂载空的卷要有数据需要容器自身会进行初始化,镜像本身声明卷定义(volume)\r\ndocker网络类型\r\nbridge(容器启动时不指定--network时的默认网络,容器可以通过ip进行相互访问)\r\nhost(容器直接使用宿主机的网络)\r\nnone(无网络)\r\ncontainer(容器网络)\r\n# 先运行一个容器\r\ndocker run -d --name web nginx\r\n# 新容器共享 web 容器的网络\r\ndocker run -d --network container:web --name sidecar alpine\r\n# sidecar 容器与 web 容器有相同的 IP 和端口\r\noverlay 跨主机容器的网络通信\r\n自定义网络\r\n创建一个network,在创建容器时候声明这个网络则此容器加入此网络中,可跟其他声明此网络的容器通信\r\ndocker的命名空间\r\n容器能不能通过-d在后台运行得看镜像本身若是服务性镜像可-d(一直运行),任务类镜像(执行任务后就关闭不能-d),基础镜像不能-d\r\ndocker容器的生命周期与它的主进程绑定\r\n\"基础镜像默认的 CMD 不适合直接 -d 运行，因为它们会立即退出。但你可以通过提供持续运行的命令来让它们在后台运行。这不是基础镜像的限制，而是使用方式的问题。\"(/bin/shell无进程会自动退出)\r\n当docker服务重启或者停止的时候容器会停止需要在daemon.json添加 \"live-restore\": true则不会停止容器\r\n关闭宿主机也会导致容器停止\r\n云上部署k8s\r\nk8s部署过程\r\n获取docker容器的负载 docker stats (实时更新)\r\n磁盘负载 docker system df\r\n容器进程 docker top 容器名\r\ndocker system prune 		清除所有未使用的资源\r\ndocker system prune -a 	强制清除\r\ndocker image prune	清理未使用的镜像\r\ndocker依赖linux内核的特定功能\r\ncmd提供的参数将成为entrypoint指定的可执行文件的参数\r\nLinux文件系统组成\r\n超级块:存储整个文件系统的元数据，例如文件系统的大小、块数量、空闲块数量、inode数量、空闲inode数量、块大小、文件系统类型等。\r\ninode:inode（索引节点）是文件系统中的一个数据结构，用于存储文件的元数据（除了文件名以外的所有信息）\r\n目录条目:目录也是一种特殊的文件，其内容是一个目录条目列表。每个目录条目将文件名映射到inode编号。\r\n数据块:实际存储文件内容或目录条目的地方。文件系统将存储空间划分为固定大小的块（如4KB），称为数据块。\r\n以查找文件/home/test.txt为例,文件系统为ext4\r\n文件系统被挂载的时候,内核读取超级快获取文件系统的整体信息(块大小,inode表位置等)\r\n内核读取inode表中的起始块地址,inode编号和大小计算出根目录的inode的位置并读取inode\r\n通过根目录下的inode的数据块指针获取到数据块,读取数据块即可获取根目录下的目录条目(文件名和对应的inode编号)\r\n内核在根目录的目录条目线性搜索文件home的inode编号\r\n通过inode编号获取到数据块通过数据块获取到/home下的目录条目\r\n然后依次类推\r\n只有创建的递归是-p其他都是-r\r\n跟用户相关的配置到用户目录下的.bash_profile,.bashrc跟全局相关的配置到/etc/profile\r\nsudo文件使用visudo命令编辑\r\nfind  \r\nlsblk查看磁盘为标准分区还是逻辑卷\r\n读操作频繁小文件众多选ext4\r\n写操作频繁大文件选择xfs\r\n分页存取机制:内核将物理内存不经常使用的数据块自动交换到虚拟内存中,经常使用的信息会保留到物理内存\r\nlsof\r\n查看哪个进程占用文件/磁盘:lsof /mnt/disk \r\n查看特定用户打开的文件:lsof -u root\r\n查看pid打开的文件数:lsof -p 1234 \r\n查看进程打开的文件数:lsof -c docker（可通过wc命令统计打开的文件数，文件数超过一千则表示进程异常）\r\npgrep查询进程的pid\r\npgrep -f docker\r\ncrontab的邮件日志需定时处理\r\ncron -e：编辑当前用户的crontab文件内容\r\ncron -l：显示用户的crontab文件内容\r\n线上服务器的优化\r\n最小化安装\r\n改变ssh端口,不使用dns发查,\r\n关闭selinux\r\n更新yum源\r\n定时更新服务器时间\r\nchattr +i   /etc/passwd (锁定重要文件)\r\n资源参数优化(系统打开最大进程数和文件数)\r\niptables防火墙由不同表组成,,不同的表定义不同的表,通过链来设置规则和策略\r\nfiler表(默认表):input链(收包),output链(发包),forward链(转发)\r\nNAT表:prerouting(数据包到防火墙时改变目的ip为内网ip),postrouting(数据包出防火墙时改变源ip为防火墙),output(改变本地产生的目的地址)\r\n查看规则:iptables -L -n  -t iptables/nat\r\n清除规则:iptables -F/-X/-Z (不能清除默认规则)\r\n规则匹配\r\n默认数据包会通过表制定的规则执行相应的动作若是制定的表的规则都不满足最后则会根据预设规则(即filer制定的规则)来执行\r\n制定规则\r\niptables -P(链) -t(表) \r\nnginx的优化\r\n进程设定多cpu进行\r\n打开最大的文件数\r\n开启高效的文件传输模式\r\n开启gzip功能\r\nkill -HUP pid(丝滑重启不中断用户请求,pid为nginx的pid)\r\nkill -QUIT pid(处理完当前请求后关闭进程)\r\n./nginx -t(检查配置文件是否有语法错误)\r\n反向代理的优化\r\n临时缓存区（roxy_buffers） :务端回应客户端请求文件的时候,通过nginx接收之后返回给客户端这个过程,通过请求不同的文件大小来设置相应的缓存区的大小减少io\r\n忙时缓存区（proxy_busy_buffers_size）:nginx接收的数据在发送给客户端这个过程就叫忙时缓存区,好处在超过忙时缓冲区所设定的数据量的时候将停止接收服务端数据,这种做法的好处是在高并发中多连接的情况下防止内存被吃满(缓存区*10000)另一个好处是低网速的客户端也能获取相对较好的体验(达到缓冲区就停止接收防止数据一股脑流入磁盘中,即慢慢发)不适合实时视频会议(出现不同步的情况)\r\n临时文件目录:当缓存区超过设置的大小则会就文件存放在磁盘下的临时文件目录中(i/o)\r\n临时文件大小（proxy_temp_file_write_size）\r\n通过临时缓冲区和临时文件目录将在服务器请求的数据返回给客户端\r\n例子:\r\n\r\nnginx负载均衡:轮询,加权轮询,ip哈希,fair,url哈希(即相同的网络请求走同一个服务器)\r\nkillall -0:检查进程是否存在\r\nlvs的dr模式\r\n负载均衡器修改mac地址为后端的mac地址,后端的服务器需绑定一个回环口来收负载器的数据包,负载器和后端需在同一个局域网内,后端服务器开启arp抑制,网关设定在上级路由器,回包不通过负载器进行回包\r\nnat模式\r\n负载均衡器修改目的ip为后端的ip地址,负载器和后端的服务器无需在同一个网段内,后端服务器的网关为负载器,通过负载器进行回包\r\ntun模式\r\n负载器跟后端形成隧道,发包通过隧道发送,回包不经过负载器,负载器不需要跟后端在同网段\r\nlvs的调度算法根据内核中的连接调度算法的实现原理,然后根据具体的业务选型\r\n有些排查命令只是排查基于操作系统表面的排查\r\npidstat 3 5 (分析cpu状态信息,输出每3s输出一次共输出5次)\r\nperf分析cpu性能问题\r\nperf(分析cpu性能) perf top(实时查看)   perf record(在当前目录下生成输出日志)  perf report(读数输出日志)\r\nperf -g -p pid（具体进程的pid）\r\n进去perf之后查看pid相关的进程的self的值(有值查看才有意义),点击打开查看是哪个代码导致出现的问题(若是在容器运行需到容器查看)\r\n代码出现问题,通过进程找到函数对应关系,通过函数调用关系找到这个函数调用消耗的资源,然后对代码进行修改来解决\r\n进程占用cpu低,系统\r\npstree查看进程之间的调用关系\r\nxtrabackup备份过程,在进行数据库备份的过程中,xtrabackup会监视redo日志将事务日志的每个数据修改记录下来然后在进行备份完成之后通过事务日志进行恢复使得备份后的数据库都一样则备份结束(恢复过程中原数据库禁止写入),在应对海量数据的备份情况可使用流特性备份\r\nmysql的主从复制(master io线程 slave io线程和sql线程,需开启binlog日志)\r\nslave通过io线程连接mysql获取日志位置和日志的内容位置\r\nmaster通过自身io将binlog日志和binlog日志记录的位置一同给slave\r\nslave获取日志将更新内容写入relay log日志中解析为sql语句并执行自身\r\nslave将日志的位置和日志记录的位置记录到master-info文件中以便迅速定位从哪个位置开始读取\r\nmha\r\n(1)Failover切换之后会产生一个app1.failover.complete文件，如果要进行第二次Failover测试，需要手工删除app1.failover.complete。另一种方法是通过--ignore_last_failover参数来忽略，例如：\r\nmasterha_master_switch --master_state=dead --conf=/etc/mha/app1.cnf  	--dead_master_host=172.16.213.236 --dead_master_port=3306 	--new_master_host=172.16.213.232 --new_master_port=3306 --ignore_last_failover\r\n(2)一旦发生一次切换后，mha manager监控进程将会退出，无法继续进行监控，要再次开启监控，需将原故障数据库重新加入到MHA环境中来，然后设置为slave。最后再次在mha manager上开启对master的监控进程。\r\n(3)原主节点重新加入到MHA时只能设置为slave,并且需要执行\r\nchange master to MASTER_HOST=\'172.16.213.236\', MASTER_USER=\'replicationuser\',MASTER_PASSWORD=\'replicationuser\',MASTER_LOG_FILE=\'mysql-bin.000004\',MASTER_LOG_POS=106;\r\n(4)关于ip地址的接管有几种方式，这里采用的是MHA自动调用ip别名的方式，好处是在能够保证数据库状态与业务Ip 切换的一致性。启动管理节点之后 vip会自动别名到当前主节点上。\r\nxenon\r\nGTID:由UUID和TID组成,UUID是Mysql实例的唯一标识(通过查看GTID辨别此GTID由哪台mysql产生),TID为提交的事务的数量(当主的数量和从的数量相同则表面相互备份的情况)\r\n工作原理:GTID记录在binlog日志中,slave端的i/o线程将变更的binlog，写入到本地的relay log中。\r\nsql线程从relay log中获取GTID，然后对比slave端的binlog是否有记录。\r\n有记录表示已经执行即忽略,没有记录则执行事务\r\n一个事务代表一个GTID','2026-01-23 09:41:40.343516'),(27,'kubeconfig','5217013752605651','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:42:34.469319'),(28,'kubeconfig','215745433721378','LVS采用三层结构,分别是:\r\n负载调度器\r\n服务池\r\n共享存储\r\nlvs优势\r\n抗负载能力强:工作方式简单工作在网络的第四层只做转发,很少出现故障\r\n配置性低:配置选项少减少人为出错\r\n工作稳定:因为抗负载能力高,有完整的双机热备方案\r\n能支持所有的应用:在第四层\r\n异步请求:lvs调度器并关心服务器是否接受是否回包\r\nLVS负载策略\r\nNAT DR TUN\r\nLVS负载算法\r\n轮询算法\r\n加权轮询算法\r\n源地址哈希\r\n目标地址哈希\r\n最小连接数调度\r\n加权最小连接数调度\r\nnginx\r\n功能相比lvs多,调整项多\r\n安装相对lvs比较简单\r\n网络依赖小,能ping通就行\r\n有日志和返回码更好的定位错误\r\n同步请求:调度器等服务器回应再返会客户端(服务器请求失败换下一个服务器请求)\r\n脑裂即VRRP双方的心跳线断开导致双方都成为master节点互抢资源导致\r\n如何解决脑裂问题\r\n使用两根心跳线路\r\n检查到脑裂现象节点发送命令让另一个节点关机\r\n做好脑裂监控报警\r\nnginx的四层负载\r\nnginx与apache的区别\r\nnginx:\r\n轻量级,占用的内存少\r\n抗并发,能抗2-3万的并发数\r\n处理静态文件能力强\r\n配置相对简单,支持正则表达式\r\n可以作为反向代理服务器使用\r\n可以作为负载均衡服务器,支持七层负载均衡\r\napache:\r\napache的rewrite的能力比nginx强\r\n支持的模块多\r\n更为成熟,bug较少\r\n处理动态页面能力强\r\n两者核心的区别在于apache是同步多线程模型,一个连接对应一个线程,而nginx是异步的,多个连接对应一个线程.\r\n正向代理的用途:提高访问速度,隐藏客户真实IP\r\n反向代理的用途:缓存,服务器的响应缓存在自己的内存中,减少服务器的压力 负载均衡,将用户的请求分配给多个服务器. 访问控制\r\nnginx的优化:\r\ngzip压缩优化\r\n禁止ip访问网站\r\n严格设置web目录权限\r\nphp配置优化\r\n进程数优化,将进程分配到多个cpu\r\n优化nginx进程的最大文件数\r\n反向代理的优化\r\nnginx的session不同步可以通过反向代理的ip哈希来解决,即固定ip只能访问固定的真实服务器,或者通过redis共享session\r\n访问一个网站的流程\r\n找本地host表然后找本地dns之后找上传dns\r\n网站灰度发布\r\n也叫金丝雀发布\r\nAB test就是一种灰度发布方式，让一部用户继续用A，一部分用户开始用B\r\n如果用户对B没有什么反对意见，那么逐步扩大范围，把所有用户都迁移到B上面 来\r\n灰度发布可以保证整体系统的稳定，在初始灰度的时候就可以发现、调整问题，以保证其影响度\r\n主从延迟产生的原因及解决方法\r\n主库并发比较高的时候,产生的DLL超过从库的sql线程所承受的范围,延迟就产生了\r\n网络抖动\r\n解决方案\r\n读写分离,一主多从,主提供写入从提供读取\r\n使用redis减少mysql压力\r\n使用更好的硬件设备减少mysql压力\r\n从服务器接受的更新不写入二进制日志\r\n禁用slave端的binlog\r\n判断主从延迟的方法\r\n通过命令show slave status查看线程运行状态(YES为正常)\r\nMysql的数据备份方式\r\nxtrabackup工具备份\r\nmysqldump工具备份\r\n基于mysqldump做备份策略:周日做全备,备份同时滚动日志\r\n周一到周六:备份二进制文件\r\n恢复的时候:完全备份+二进制文件中到此处的事件\r\ninnodb的特征\r\n插入缓冲\r\n二次写\r\n自适应哈希\r\n预读\r\n如何加强mysql安全\r\n避免直接从互联网连接数据库,确保特定主机的访问权限\r\n定期备份数据库\r\n禁用或限制远程访问\r\n移除匿名用户或者废弃的账户\r\n限制mysql数据库用户的权限\r\n一主多从中从库宕机,如何手工恢复\r\n停止slave\r\n导入备份数据\r\n配置master服务器为自己的主服务器\r\n启动slave\r\n检查从库状态\r\nmysql中myisam与innodb的区别\r\ninnodb支持事务\r\n支持行级锁\r\n支持外键\r\n支持全文索引\r\n数据库导致的网站打开慢如何排查\r\n检查操作系统的负载\r\n登录mysql查看哪些sql语句占用时间过长\r\n优化sql语句,建立索引 \r\n\r\n使用的监控项是能否连接指定端口,检查服务能不能接受tcp连接,服务的性能\r\n邮件报警\r\n在模板中设置监控项和触发器在触发器动作中添加此模板的触发器和再设置告警媒介再在用户中设置报警媒介(通过此用户发送给收件人)\r\n在需要监控的主机上安装agent然后配置文件修改host和server然后在web界面添加监控主机即可\r\n\r\n\r\n项目出现的问题,项目是如何实现的,项目为什么要这么设计\r\n\r\n优缺点\r\n\r\nkeepalived+mysql+mha 老师项目\r\nnginx \r\nzabbix\r\n再生龙生成镜像然后+rsync进行镜像备份\r\n\r\n\r\n\r\n项目出现的一切问题\r\n项目得会给圆过来\r\n园项目？还是接着走？\r\n换成真实的项目？\r\n','2026-01-23 09:42:44.349860'),(29,'kubeconfig','22827946750941275','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:53:38.977470'),(30,'kubeconfig','29248443766127996','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:55:04.652318'),(31,'kubeconfig','5628713859254866','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 09:56:40.230828'),(32,'kubeconfig','9858169172466726','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 10:05:54.965551'),(33,'kubeconfig','2956608181582965','https://mirrors.tuna.tsinghua.edu.cn/jenkins/updates/update-center.json\r\n\r\n\r\npipeline {\r\n    //在名为kubernetes的Agent中执行流水线，会拉起一个Slave Pod\r\n    agent {\r\n        kubernetes {\r\n            cloud \'Slave\'\r\n            yaml \'\'\'\r\n            apiVersion: v1\r\n            kind: Pod\r\n            spec:\r\n              volumes: \r\n              - name: data\r\n                nfs:\r\n                  server: 192.168.37.147\r\n                  path: /nfs/maven \r\n              - name: dockersocket\r\n                hostPath:\r\n                  path: /run/docker.sock\r\n              containers:\r\n              - name: maven\r\n                image: 8.138.232.71:82/cicd/maven:3.8.6\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: data\r\n                  mountPath: /root/.m2 \r\n              - name: nodejs\r\n                image: 8.138.232.71:82/cicd/nodejs:14.20\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: sonar\r\n                image: 8.138.232.71:82/cicd/sonar-scanner:2.3.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: docker\r\n                image: 8.138.232.71:82/cicd/docker:20.10\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: dockersocket\r\n                  mountPath: /run/docker.sock \r\n              - name: kubectl\r\n                image: 8.138.232.71:82/cicd/kubectl:1.23.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n            \'\'\'\r\n        }\r\n    }\r\n    stages {\r\n        stage(\'maven测试\') {\r\n            steps {\r\n              container(\'maven\'){\r\n                sh \'mvn --version\'\r\n              }\r\n            }\r\n        }\r\n        stage(\'nodejs测试\'){\r\n            steps{\r\n              container(\'nodejs\'){\r\n                sh \'node -v\'\r\n              }\r\n        	}\r\n        }\r\n        stage(\'docker测试\'){\r\n          steps{\r\n            container(\'docker\'){\r\n              sh \'docker ps\'\r\n            }\r\n          }\r\n        }\r\n        stage(\'kubectl测试\'){\r\n          steps{\r\n            container(\'kubectl\'){\r\n              sh \'kubectl version\'\r\n            }\r\n          }\r\n        }\r\n    }\r\n}\r\n\r\n\r\nFSxCDysyNqoYbK_y1QzD\r\n\r\n\r\ncheckout scmGit(branches: [[name: \'*/master\']], extensions: [], userRemoteConfigs: [[credentialsId: \'gitlab-root-token\', url: \'http://web.gitlab.com/root/ruoyo-cloud.git\']])\r\n\r\n\r\n172.16.32.133\r\n\r\n\r\ngateway部署探测探测8080端口\r\n\r\n\r\n\r\n\r\nwithSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n\r\n\r\n\r\n\r\n优化:对每个组件进行创建对应项目实现单个组件的部署\r\n设置当单个组件的代码改变时候只对\r\n对组件进行限值内存和cpu\r\nprometheus监控数据\r\npipe流水线优化:并行构建,代码检测,检测通知,变量标签,定义定时任务删除因多改动导致的多镜像所造成的资源\r\n监控\r\nsum(container_memory_working_set_bytes{container!=\"\",namespace=\"ruoyi-cloud\"}) by (pod)/1024/1024/1024：查看ruoyi下的pod的内存使用量\r\n\r\n\r\n\r\n\r\n\r\npipeline {\r\n    //在名为kubernetes的Agent中执行流水线\r\n    agent {\r\n        kubernetes {\r\n            cloud \'kubernetes\'\r\n            yaml \'\'\'\r\n            apiVersion: v1\r\n            kind: Pod\r\n            spec:\r\n              nodeSelector:\r\n                disk: cicd\r\n              volumes: \r\n              - name: data\r\n                nfs:\r\n                  server: 192.168.37.147\r\n                  path: /nfs/maven \r\n              - name: dockersocket\r\n                hostPath:\r\n                  path: /run/docker.sock\r\n              containers:\r\n              - name: maven\r\n                image: 8.138.232.71:82/cicd/maven:3.8.6\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: data\r\n                  mountPath: /root/.m2 \r\n              - name: nodejs\r\n                image: 8.138.232.71:82/cicd/nodejs:14.20\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: sonar\r\n                image: 8.138.232.71:82/cicd/sonar-scanner:2.3.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n              - name: docker\r\n                image: 8.138.232.71:82/cicd/docker:20.10\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n                volumeMounts:\r\n                - name: dockersocket\r\n                  mountPath: /run/docker.sock \r\n              - name: kubectl\r\n                image: 8.138.232.71:82/cicd/kubectl:1.23.0\r\n                imagePullPolicy: IfNotPresent\r\n                command: [\"cat\"]\r\n                tty: true\r\n            \'\'\'\r\n        }\r\n    }\r\n\r\n    //定义全局变量\r\n    environment{\r\n      //修改仓库地址\r\n      Gitlab_URL = \'http://web.gitlab.com/root/ruoyo-cloud.git\'\r\n  \r\n      //认证的token无需修改，这个token前边创建时是全局token\r\n      Gitlab_token = \'gitlab-root-token\'\r\n    }\r\n\r\n    stages {\r\n        stage(\'拉取项目\') {\r\n            steps {\r\n              container(\'maven\'){\r\n                checkout scmGit(branches: [[name: \'*/master\']], extensions: [], userRemoteConfigs: [[credentialsId: \"$Gitlab_token\", url: \"$Gitlab_URL\"]])\r\n\r\n                //查看项目文件\r\n                sh \'ls -l\'\r\n\r\n                //查看当前项目所在路径\r\n                sh \'pwd\'\r\n              }\r\n            }\r\n        }\r\n        stage(\'项目检测\'){\r\n          //通过parallel属性同时执行多个步骤来检测代码\r\n          parallel{\r\n            //定义步骤\r\n            stage(\'检测Gateway\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测Auth\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测System\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'检测Monitor\'){\r\n              //把需要检测的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致，最终要切换到该目录内，才能对该目录下的项目进行检测\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              //在步骤中执行的指令\r\n              steps{\r\n                //withSonarQubeEnv是集成SonarQube属性，引用前边在jenkins中创建的sonar-k8s令牌就可以访问SonarQube，并通过以下方式对项目进行检测\r\n                withSonarQubeEnv(\'sonar-k8s\'){\r\n                  container(\'sonar\'){\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sonar-scanner \\\r\n                        -Dsonar.projectKey=${AppName} \\\r\n                        -Dsonar.sources=. \\\r\n                        -Dsonar.java.binaries=src\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'检测结果\'){\r\n          steps{\r\n              container(\'sonar\'){\r\n                script{\r\n                  timeout(5){\r\n                    def qg = waitForQualityGate()\r\n                    if (qg.status != \'OK\'){\r\n                      error \"检测失败，失败的原因: ${qg.status}\"\r\n                    }\r\n                  }\r\n                }\r\n              }\r\n          }\r\n        }\r\n        stage(\'项目编译\'){\r\n          //通过parallel属性同时执行多个步骤来构建项目\r\n          parallel{\r\n            //定义步骤\r\n            stage(\'编译Gateway\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译Auth\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译System\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                  //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译Monitor\'){\r\n              //把需要编译的项目名称定义到环境变量中在下边调用，项目名称要与实际检测的项目目录保持一致\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              steps{\r\n                container(\'maven\'){\r\n                //把需要编译的项目路径存储到变量中，然后在下边调用变量对目录下的项目进行编译(不需要切换到路径内)\r\n                sh \'Build_Path=$(find ./ -type d -name \"${AppName}\") && \\\r\n                    mvn package -Dmaven.test.skip=true -pl ${Build_Path} -am\'\r\n                }\r\n              }\r\n            }\r\n            //定义步骤\r\n            stage(\'编译UI\'){\r\n              environment{\r\n                AppName = \"ruoyi-ui\"\r\n              }\r\n              steps {\r\n                container(\'nodejs\'){\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      npm install --registry=https://registry.npmmirror.com && \\\r\n                      npm run build:prod\'\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        //该步骤无需修改\r\n        stage(\'生成镜像Tag\'){\r\n          steps{\r\n            container(\'maven\'){\r\n              script{\r\n                //获取本次git提交的commit的ID（git log -n1 --pretty=format:%h），并把ID存储到变量中\r\n                env.COMMITID = sh(returnStdout: true, script: \"git log -n1 --pretty=format:%h\").trim()\r\n                //获取本次镜像的构建时间（date +%Y%m%d_%H%M）,并把时间存储到变量中\r\n                env.BuildTime = sh(returnStdout: true, script: \"date +%Y%m%d_%H%M\").trim()\r\n                //完整的镜像Tag\r\n                env.ImageTag = COMMITID + \"_\" + BuildTime\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'构建镜像\'){\r\n          //通过parallel属性同时执行多个步骤来构建镜像\r\n          parallel{\r\n            stage(\'构建Gateway镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建Auth镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建System镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建Monitor镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n            stage(\'构建UI镜像\'){\r\n              environment{\r\n                AppName=\"ruoyi-ui\"\r\n              }\r\n              steps{\r\n                container(\'docker\'){\r\n                  //登录仓库\r\n                  sh \'docker login 192.168.37.147:80 -u zy -p A86564728aa\'\r\n                  //构建镜像,提前创建好ruoyi公开仓库,构建镜像时在项目仓库有提前准备好的Dockerfile文件及Skywalking-agent\r\n                  sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                      docker build -f dockerfile -t 192.168.37.147:80/ruoyi/${AppName}:${ImageTag} .\'\r\n                  //上传镜像到仓库,提前在harbor中创建好对应的仓库\r\n                  sh \'docker push 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                  //删除镜像,镜像是在节点上构建,上传到仓库后删除即可\r\n                  sh \'docker rmi 192.168.37.147:80/ruoyi/${AppName}:${ImageTag}\'\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n        stage(\'项目部署\'){\r\n          //通过parallel属性同时执行多个步骤来构建镜像\r\n          parallel{\r\n            stage(\'部署Gateway\'){\r\n              environment{\r\n                AppName=\"ruoyi-gateway\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-gateway:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署Auth\'){\r\n              environment{\r\n                AppName=\"ruoyi-auth\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-auth:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署System\'){\r\n              environment{\r\n                AppName=\"ruoyi-system\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-system:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署Monitor\'){\r\n              environment{\r\n                AppName=\"ruoyi-monitor\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-monitor:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n            stage(\'部署UI\'){\r\n              environment{\r\n                AppName=\"ruoyi-ui\"\r\n              }\r\n              steps{\r\n                container(\'kubectl\'){\r\n                  withCredentials([file(credentialsId: \'kubernetes-admin-config\', variable: \'KUBECONFIG\')]) {\r\n                    sh \'mkdir -p ~./kube && cp ${KUBECONFIG} ~./kube/config\'\r\n                    //替换deploy.yaml文件中的{NameSpace}与{Image}部分，替换成实际的名称空间和镜像\r\n                    sh \'cd $(find ./ -type d -name \"${AppName}\") && \\\r\n                        sed -i \"s#{NameSpace}#ruoyi-cloud#g\" deploy.yml && \\\r\n                        sed -i \"s#{Image}#192.168.37.147:80/ruoyi/ruoyi-ui:${ImageTag}#g\" deploy.yml && \\\r\n                        kubectl apply -f deploy.yml\'\r\n                  }\r\n                }\r\n              }\r\n            }\r\n          }\r\n        }\r\n    }\r\n}\r\n\r\n\r\nkubectl exec -it argocd-repo-server-6b4b89dd7c-gcp54 -n argocd -- /bin/sh\r\njMVY7KxZ6dA6W3_2HFmp\r\n10.96.106.218\r\n修改打开的最大文件数\r\n\r\n\r\n#！/bin/bash\r\nshell是基于于内核进行交互的语言无需进行编译就可直接输出\r\ngrep    查找文件内容   -c :输出匹配的行 	-n:输出匹配的值,并标出行号	-v:输出不匹配的值\r\n“”和‘’的区别 \"\"会输出变量的值而‘’当正常字符使用\r\n正则表达式 \\     \\<the\\>   [a-c]     \\{\\}  grep \r\nunset readonly\r\n${}\r\n\'\' “”``  \\\r\nread  $?  \r\n${}\r\n${!var}\r\n${var/1/2}\r\n${var/#1/2}\r\n${var/%1/2}\r\n${! *}\r\n${#var}\r\n${var:m} ${var:m:len} \r\neval(值的二次引用)\r\ncat 1.txt <<EOF\r\nSD S \r\nS AD \r\nS DA\r\nEOF\r\n[ -z var ]\r\n[ -n var ]\r\n[ a -a b ]\r\n[ b -o c ]\r\n[ ! c ]\r\n-f -L -d -e -s -r -w -x \r\nNF NR\r\n;: && || \r\ndmesg\r\ntail -n -f \r\ncontainerd\r\ndocker inspect \r\ngrep -A 5 -B 5\r\ngrep -C 5(行前后)\r\ndocker -v(--mount)\r\n容器的目录挂载空的卷要有数据需要容器自身会进行初始化,镜像本身声明卷定义(volume)\r\ndocker网络类型\r\nbridge(容器启动时不指定--network时的默认网络,容器可以通过ip进行相互访问)\r\nhost(容器直接使用宿主机的网络)\r\nnone(无网络)\r\ncontainer(容器网络)\r\n# 先运行一个容器\r\ndocker run -d --name web nginx\r\n# 新容器共享 web 容器的网络\r\ndocker run -d --network container:web --name sidecar alpine\r\n# sidecar 容器与 web 容器有相同的 IP 和端口\r\noverlay 跨主机容器的网络通信\r\n自定义网络\r\n创建一个network,在创建容器时候声明这个网络则此容器加入此网络中,可跟其他声明此网络的容器通信\r\ndocker的命名空间\r\n容器能不能通过-d在后台运行得看镜像本身若是服务性镜像可-d(一直运行),任务类镜像(执行任务后就关闭不能-d),基础镜像不能-d\r\ndocker容器的生命周期与它的主进程绑定\r\n\"基础镜像默认的 CMD 不适合直接 -d 运行，因为它们会立即退出。但你可以通过提供持续运行的命令来让它们在后台运行。这不是基础镜像的限制，而是使用方式的问题。\"(/bin/shell无进程会自动退出)\r\n当docker服务重启或者停止的时候容器会停止需要在daemon.json添加 \"live-restore\": true则不会停止容器\r\n关闭宿主机也会导致容器停止\r\n云上部署k8s\r\nk8s部署过程\r\n获取docker容器的负载 docker stats (实时更新)\r\n磁盘负载 docker system df\r\n容器进程 docker top 容器名\r\ndocker system prune 		清除所有未使用的资源\r\ndocker system prune -a 	强制清除\r\ndocker image prune	清理未使用的镜像\r\ndocker依赖linux内核的特定功能\r\ncmd提供的参数将成为entrypoint指定的可执行文件的参数\r\nLinux文件系统组成\r\n超级块:存储整个文件系统的元数据，例如文件系统的大小、块数量、空闲块数量、inode数量、空闲inode数量、块大小、文件系统类型等。\r\ninode:inode（索引节点）是文件系统中的一个数据结构，用于存储文件的元数据（除了文件名以外的所有信息）\r\n目录条目:目录也是一种特殊的文件，其内容是一个目录条目列表。每个目录条目将文件名映射到inode编号。\r\n数据块:实际存储文件内容或目录条目的地方。文件系统将存储空间划分为固定大小的块（如4KB），称为数据块。\r\n以查找文件/home/test.txt为例,文件系统为ext4\r\n文件系统被挂载的时候,内核读取超级快获取文件系统的整体信息(块大小,inode表位置等)\r\n内核读取inode表中的起始块地址,inode编号和大小计算出根目录的inode的位置并读取inode\r\n通过根目录下的inode的数据块指针获取到数据块,读取数据块即可获取根目录下的目录条目(文件名和对应的inode编号)\r\n内核在根目录的目录条目线性搜索文件home的inode编号\r\n通过inode编号获取到数据块通过数据块获取到/home下的目录条目\r\n然后依次类推\r\n只有创建的递归是-p其他都是-r\r\n跟用户相关的配置到用户目录下的.bash_profile,.bashrc跟全局相关的配置到/etc/profile\r\nsudo文件使用visudo命令编辑\r\nfind  \r\nlsblk查看磁盘为标准分区还是逻辑卷\r\n读操作频繁小文件众多选ext4\r\n写操作频繁大文件选择xfs\r\n分页存取机制:内核将物理内存不经常使用的数据块自动交换到虚拟内存中,经常使用的信息会保留到物理内存\r\nlsof\r\n查看哪个进程占用文件/磁盘:lsof /mnt/disk \r\n查看特定用户打开的文件:lsof -u root\r\n查看pid打开的文件数:lsof -p 1234 \r\n查看进程打开的文件数:lsof -c docker（可通过wc命令统计打开的文件数，文件数超过一千则表示进程异常）\r\npgrep查询进程的pid\r\npgrep -f docker\r\ncrontab的邮件日志需定时处理\r\ncron -e：编辑当前用户的crontab文件内容\r\ncron -l：显示用户的crontab文件内容\r\n线上服务器的优化\r\n最小化安装\r\n改变ssh端口,不使用dns发查,\r\n关闭selinux\r\n更新yum源\r\n定时更新服务器时间\r\nchattr +i   /etc/passwd (锁定重要文件)\r\n资源参数优化(系统打开最大进程数和文件数)\r\niptables防火墙由不同表组成,,不同的表定义不同的表,通过链来设置规则和策略\r\nfiler表(默认表):input链(收包),output链(发包),forward链(转发)\r\nNAT表:prerouting(数据包到防火墙时改变目的ip为内网ip),postrouting(数据包出防火墙时改变源ip为防火墙),output(改变本地产生的目的地址)\r\n查看规则:iptables -L -n  -t iptables/nat\r\n清除规则:iptables -F/-X/-Z (不能清除默认规则)\r\n规则匹配\r\n默认数据包会通过表制定的规则执行相应的动作若是制定的表的规则都不满足最后则会根据预设规则(即filer制定的规则)来执行\r\n制定规则\r\niptables -P(链) -t(表) \r\nnginx的优化\r\n进程设定多cpu进行\r\n打开最大的文件数\r\n开启高效的文件传输模式\r\n开启gzip功能\r\nkill -HUP pid(丝滑重启不中断用户请求,pid为nginx的pid)\r\nkill -QUIT pid(处理完当前请求后关闭进程)\r\n./nginx -t(检查配置文件是否有语法错误)\r\n反向代理的优化\r\n临时缓存区（roxy_buffers） :务端回应客户端请求文件的时候,通过nginx接收之后返回给客户端这个过程,通过请求不同的文件大小来设置相应的缓存区的大小减少io\r\n忙时缓存区（proxy_busy_buffers_size）:nginx接收的数据在发送给客户端这个过程就叫忙时缓存区,好处在超过忙时缓冲区所设定的数据量的时候将停止接收服务端数据,这种做法的好处是在高并发中多连接的情况下防止内存被吃满(缓存区*10000)另一个好处是低网速的客户端也能获取相对较好的体验(达到缓冲区就停止接收防止数据一股脑流入磁盘中,即慢慢发)不适合实时视频会议(出现不同步的情况)\r\n临时文件目录:当缓存区超过设置的大小则会就文件存放在磁盘下的临时文件目录中(i/o)\r\n临时文件大小（proxy_temp_file_write_size）\r\n通过临时缓冲区和临时文件目录将在服务器请求的数据返回给客户端\r\n例子:\r\n\r\nnginx负载均衡:轮询,加权轮询,ip哈希,fair,url哈希(即相同的网络请求走同一个服务器)\r\nkillall -0:检查进程是否存在\r\nlvs的dr模式\r\n负载均衡器修改mac地址为后端的mac地址,后端的服务器需绑定一个回环口来收负载器的数据包,负载器和后端需在同一个局域网内,后端服务器开启arp抑制,网关设定在上级路由器,回包不通过负载器进行回包\r\nnat模式\r\n负载均衡器修改目的ip为后端的ip地址,负载器和后端的服务器无需在同一个网段内,后端服务器的网关为负载器,通过负载器进行回包\r\ntun模式\r\n负载器跟后端形成隧道,发包通过隧道发送,回包不经过负载器,负载器不需要跟后端在同网段\r\nlvs的调度算法根据内核中的连接调度算法的实现原理,然后根据具体的业务选型\r\n有些排查命令只是排查基于操作系统表面的排查\r\npidstat 3 5 (分析cpu状态信息,输出每3s输出一次共输出5次)\r\nperf分析cpu性能问题\r\nperf(分析cpu性能) perf top(实时查看)   perf record(在当前目录下生成输出日志)  perf report(读数输出日志)\r\nperf -g -p pid（具体进程的pid）\r\n进去perf之后查看pid相关的进程的self的值(有值查看才有意义),点击打开查看是哪个代码导致出现的问题(若是在容器运行需到容器查看)\r\n代码出现问题,通过进程找到函数对应关系,通过函数调用关系找到这个函数调用消耗的资源,然后对代码进行修改来解决\r\n进程占用cpu低,系统\r\npstree查看进程之间的调用关系\r\nxtrabackup备份过程,在进行数据库备份的过程中,xtrabackup会监视redo日志将事务日志的每个数据修改记录下来然后在进行备份完成之后通过事务日志进行恢复使得备份后的数据库都一样则备份结束(恢复过程中原数据库禁止写入),在应对海量数据的备份情况可使用流特性备份\r\nmysql的主从复制(master io线程 slave io线程和sql线程,需开启binlog日志)\r\nslave通过io线程连接mysql获取日志位置和日志的内容位置\r\nmaster通过自身io将binlog日志和binlog日志记录的位置一同给slave\r\nslave获取日志将更新内容写入relay log日志中解析为sql语句并执行自身\r\nslave将日志的位置和日志记录的位置记录到master-info文件中以便迅速定位从哪个位置开始读取\r\nmha\r\n(1)Failover切换之后会产生一个app1.failover.complete文件，如果要进行第二次Failover测试，需要手工删除app1.failover.complete。另一种方法是通过--ignore_last_failover参数来忽略，例如：\r\nmasterha_master_switch --master_state=dead --conf=/etc/mha/app1.cnf  	--dead_master_host=172.16.213.236 --dead_master_port=3306 	--new_master_host=172.16.213.232 --new_master_port=3306 --ignore_last_failover\r\n(2)一旦发生一次切换后，mha manager监控进程将会退出，无法继续进行监控，要再次开启监控，需将原故障数据库重新加入到MHA环境中来，然后设置为slave。最后再次在mha manager上开启对master的监控进程。\r\n(3)原主节点重新加入到MHA时只能设置为slave,并且需要执行\r\nchange master to MASTER_HOST=\'172.16.213.236\', MASTER_USER=\'replicationuser\',MASTER_PASSWORD=\'replicationuser\',MASTER_LOG_FILE=\'mysql-bin.000004\',MASTER_LOG_POS=106;\r\n(4)关于ip地址的接管有几种方式，这里采用的是MHA自动调用ip别名的方式，好处是在能够保证数据库状态与业务Ip 切换的一致性。启动管理节点之后 vip会自动别名到当前主节点上。\r\nxenon\r\nGTID:由UUID和TID组成,UUID是Mysql实例的唯一标识(通过查看GTID辨别此GTID由哪台mysql产生),TID为提交的事务的数量(当主的数量和从的数量相同则表面相互备份的情况)\r\n工作原理:GTID记录在binlog日志中,slave端的i/o线程将变更的binlog，写入到本地的relay log中。\r\nsql线程从relay log中获取GTID，然后对比slave端的binlog是否有记录。\r\n有记录表示已经执行即忽略,没有记录则执行事务\r\n一个事务代表一个GTID','2026-01-23 10:06:15.933040'),(34,'kubeconfig','2465118528625102','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 10:06:45.519016'),(35,'kubeconfig','928116619611507','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 10:10:50.660461'),(36,'kubeconfig','5710359689209251','apiVersion: v1\nclusters:\n- cluster:\n    certificate-authority-data: \n    server: https://192.168.37.200:6443\n  name: kubernetes\ncontexts:\n- context:\n    cluster: kubernetes\n    user: admin\n  name: kubernetes\ncurrent-context: kubernetes\nkind: Config\npreferences: {}\nusers:\n- name: admin\n  user:\n    client-certificate-data: \n    client-key-data: \n','2026-01-23 11:28:02.163838'),(37,'kubeconfig','6871237155342629','apiVersion: v1\nclusters:\n- cl